def transform2(g):
    h,w=len(g),len(g[0])
    shapes={}
    for r in range(h-2):
        for c in range(w-2):
            col=g[r+1][c+1]
            if col==0 or col in shapes: continue
            pat=[[g[r+i][c+j] for j in range(3)] for i in range(3)]
            if any(pat[i][j]==col for i,j in [(0,0),(0,2),(2,0),(2,2)]) or not any(pat[i][j]==col for i,j in [(0,1),(1,0),(1,2),(2,1)]):
                continue
            shapes[col]=(c,pat)  # center col = c+1
    out=[[] for _ in range(3)]
    for col in sorted(shapes,key=lambda k:shapes[k][0]):
        pat=shapes[col][1]
        for i in range(3): out[i]+=pat[i]
    return out
